import Foundation
import SwiftData
import CryptoKit

// Hush Sync: optional, end-to-end encrypted sync with your own hush-server.
// Nothing here runs unless you turn sync on in Settings > Sync. The wire format is
// described in docs/sync-protocol.md so other apps (Android, desktop) can speak it.

/// A SwiftData model that can be synced. Conformances are generated by scripts/gen_sync.py.
protocol SyncModel: PersistentModel {
    static var syncType: String { get }
    var syncID: UUID { get }
    func syncSetID(_ newID: UUID)
    static func syncNew() -> Self
    func syncEncode(_ e: SyncEncoder)
    func syncDecode(_ d: SyncDecoder)
}

extension SyncModel {
    static func syncFetchAll(_ ctx: ModelContext) -> [any SyncModel] {
        ((try? ctx.fetch(FetchDescriptor<Self>())) ?? []).map { $0 as any SyncModel }
    }
    static func syncInsertNew(_ ctx: ModelContext) -> any SyncModel {
        let o = syncNew()
        ctx.insert(o)
        return o
    }
    func syncDelete(from ctx: ModelContext) { ctx.delete(self) }
}

// MARK: - Field encoding

/// Turns a model into plain JSON fields. Dates are seconds since 1970, UUIDs are strings,
/// Data is base64, and large attachments become references to separately uploaded blobs.
final class SyncEncoder {
    private(set) var fields: [String: Any] = [:]
    /// Blobs this record refers to: blob id -> (local bytes, sealed with this iPhone's key?)
    private(set) var blobs: [String: (raw: Data, sealed: Bool)] = [:]
    private let namer: (Data, Bool) -> String?

    init(namer: @escaping (Data, Bool) -> String?) { self.namer = namer }

    func string(_ k: String, _ v: String) { fields[k] = v }
    func int(_ k: String, _ v: Int) { fields[k] = v }
    func double(_ k: String, _ v: Double) { fields[k] = v.isFinite ? v : 0 }
    func bool(_ k: String, _ v: Bool) { fields[k] = v }
    func date(_ k: String, _ v: Date?) { fields[k] = v.map { $0.timeIntervalSince1970 as Any } ?? NSNull() }
    func uuid(_ k: String, _ v: UUID?) { fields[k] = v.map { $0.uuidString as Any } ?? NSNull() }
    func data(_ k: String, _ v: Data?) { fields[k] = v.map { $0.base64EncodedString() as Any } ?? NSNull() }
    func strings(_ k: String, _ v: [String]) { fields[k] = v }
    func uuids(_ k: String, _ v: [UUID]) { fields[k] = v.map(\.uuidString) }

    /// A small field encrypted with this iPhone's key: sent as plaintext base64 inside the
    /// (sync-key encrypted) record so other devices can read it.
    func sealed(_ k: String, _ v: Data) {
        if v.isEmpty { fields[k] = ""; return }
        if let plain = DataCrypto.open(v) { fields[k] = plain.base64EncodedString() }
    }

    func blob(_ k: String, _ v: Data?, sealed: Bool) {
        guard let v else { fields[k] = NSNull(); return }
        if v.isEmpty { fields[k] = ""; return }
        guard let id = namer(v, sealed) else { return }
        fields[k] = ["blob": id]
        blobs[id] = (v, sealed)
    }
}

final class SyncDecoder {
    let fields: [String: Any]
    private let blobData: [String: Data]
    private let onSealedBlob: (Data, Data) -> Void

    init(fields: [String: Any], blobData: [String: Data], onSealedBlob: @escaping (_ raw: Data, _ plain: Data) -> Void) {
        self.fields = fields
        self.blobData = blobData
        self.onSealedBlob = onSealedBlob
    }

    func has(_ k: String) -> Bool { fields[k] != nil }
    func string(_ k: String) -> String? { fields[k] as? String }
    func int(_ k: String) -> Int? { (fields[k] as? NSNumber)?.intValue }
    func double(_ k: String) -> Double? { (fields[k] as? NSNumber)?.doubleValue }
    func bool(_ k: String) -> Bool? { (fields[k] as? NSNumber)?.boolValue }
    func date(_ k: String) -> Date? { (fields[k] as? NSNumber).map { Date(timeIntervalSince1970: $0.doubleValue) } }
    func uuid(_ k: String) -> UUID? { (fields[k] as? String).flatMap { UUID(uuidString: $0) } }
    func data(_ k: String) -> Data? { (fields[k] as? String).flatMap { Data(base64Encoded: $0) } }
    func strings(_ k: String) -> [String]? { fields[k] as? [String] }
    func uuids(_ k: String) -> [UUID]? { (fields[k] as? [String])?.compactMap { UUID(uuidString: $0) } }

    func sealed(_ k: String) -> Data? {
        guard let s = fields[k] as? String else { return nil }
        if s.isEmpty { return Data() }
        guard let plain = Data(base64Encoded: s) else { return nil }
        return DataCrypto.seal(plain)
    }

    func blob(_ k: String, sealed: Bool) -> Data? {
        if let s = fields[k] as? String, s.isEmpty { return Data() }
        guard let ref = fields[k] as? [String: Any], let id = ref["blob"] as? String, let plain = blobData[id] else { return nil }
        guard sealed else { return plain }
        let raw = DataCrypto.seal(plain)
        onSealedBlob(raw, plain)
        return raw
    }

    func optionalBlob(_ k: String, sealed: Bool) -> Data? {
        if fields[k] is NSNull { return nil }
        return blob(k, sealed: sealed)
    }

    /// Blob ids a record refers to.
    static func blobIDs(in fields: [String: Any]) -> [String] {
        fields.values.compactMap { ($0 as? [String: Any])?["blob"] as? String }
    }
}

// MARK: - Crypto

enum SyncCrypto {
    static let iterations = 600_000
    private static let checkText = Data("hush-sync-check-v1".utf8)

    /// PBKDF2-HMAC-SHA256 of the NFC-normalized passphrase. Slow on purpose; call off the main thread.
    static func deriveKey(_ passphrase: String, salt: Data, iterations: Int) -> SymmetricKey {
        let normalized = passphrase.precomposedStringWithCanonicalMapping
        return SymmetricKey(data: Passcode.pbkdf2(normalized, salt: salt, rounds: UInt32(iterations)))
    }

    static func makeCheck(_ key: SymmetricKey) -> Data { seal(checkText, key: key, context: "vault") ?? Data() }

    static func verifyCheck(_ check: Data, key: SymmetricKey) -> Bool { open(check, key: key, context: "vault") == checkText }

    /// AES-256-GCM, output nonce(12) || ciphertext || tag(16); `context` is bound as associated data.
    static func seal(_ data: Data, key: SymmetricKey, context: String) -> Data? {
        try? AES.GCM.seal(data, using: key, authenticating: Data(context.utf8)).combined
    }

    static func open(_ data: Data, key: SymmetricKey, context: String) -> Data? {
        guard let box = try? AES.GCM.SealedBox(combined: data) else { return nil }
        return try? AES.GCM.open(box, using: key, authenticating: Data(context.utf8))
    }

    static func sha256(_ d: Data) -> String { SHA256.hash(data: d).map { String(format: "%02x", $0) }.joined() }

    /// Content-addressed blob name that reveals nothing about the content without the key.
    static func blobID(plainHash: String, key: SymmetricKey) -> String {
        let mac = HMAC<SHA256>.authenticationCode(for: Data(("blob:" + plainHash).utf8), using: key)
        let b64 = Data(mac).base64EncodedString()
            .replacingOccurrences(of: "+", with: "-").replacingOccurrences(of: "/", with: "_").replacingOccurrences(of: "=", with: "")
        return "b" + b64.prefix(40)
    }

    static func canonicalJSON(_ obj: Any) -> Data {
        (try? JSONSerialization.data(withJSONObject: obj, options: [.sortedKeys, .withoutEscapingSlashes])) ?? Data()
    }
}

// MARK: - Settings (UserDefaults + Keychain)

enum SyncSettings {
    private static let d = UserDefaults.standard

    static var enabled: Bool {
        get { d.bool(forKey: "sync.enabled") }
        set { d.set(newValue, forKey: "sync.enabled") }
    }
    static var serverURL: String {
        get { d.string(forKey: "sync.url") ?? "" }
        set { d.set(newValue, forKey: "sync.url") }
    }
    static var includeVault: Bool {
        get { d.bool(forKey: "sync.vault") }
        set { d.set(newValue, forKey: "sync.vault") }
    }
    /// Minutes between automatic syncs while Hush is open; 0 = only on open, close and Sync Now.
    static var intervalMinutes: Int {
        get { d.object(forKey: "sync.interval") as? Int ?? 5 }
        set { d.set(newValue, forKey: "sync.interval") }
    }
    static var token: String? {
        get { Keychain.load("sync.token").map { String(decoding: $0, as: UTF8.self) } }
        set { if let newValue { Keychain.save(Data(newValue.utf8), for: "sync.token") } else { Keychain.delete("sync.token") } }
    }
    static var key: SymmetricKey? {
        get { Keychain.load("sync.key").flatMap { $0.count == 32 ? SymmetricKey(data: $0) : nil } }
        set {
            if let newValue { Keychain.save(newValue.withUnsafeBytes { Data($0) }, for: "sync.key") } else { Keychain.delete("sync.key") }
        }
    }
    static var isConfigured: Bool { enabled && !serverURL.isEmpty && token != nil && key != nil }

    /// Accepts "hush.tailnet.ts.net", "100.64.0.5:8080" or a full URL.
    static func normalizedURL(_ s: String) -> URL? {
        var t = s.trimmingCharacters(in: .whitespacesAndNewlines)
        while t.hasSuffix("/") { t.removeLast() }
        guard !t.isEmpty else { return nil }
        if !t.contains("://") {
            let host = t.split(separator: ":").first.map(String.init) ?? t
            let local = host.first?.isNumber == true || host.hasSuffix(".local") || !host.contains(".")
            t = (local ? "http://" : "https://") + t
        }
        guard let u = URL(string: t), u.host() != nil, ["http", "https"].contains(u.scheme ?? "") else { return nil }
        return u
    }
}

// MARK: - Local sync state

struct SyncState: Codable {
    struct Entry: Codable {
        var type: String
        var hash: String
        var seq: UInt64
    }
    var serverSeq: UInt64 = 0
    var entries: [String: Entry] = [:]
    var uploadedBlobs: Set<String> = []
    /// SHA-256 of an attachment as stored locally (sealed) -> SHA-256 of its plaintext.
    var plainHashes: [String: String] = [:]

    private static var url: URL? {
        guard let dir = FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first?
            .appendingPathComponent("HushSync", isDirectory: true) else { return nil }
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir.appendingPathComponent("state.json")
    }

    static func load() -> SyncState {
        guard let url, let data = try? Data(contentsOf: url), let s = try? JSONDecoder().decode(SyncState.self, from: data) else { return SyncState() }
        return s
    }

    func save() {
        guard let url = Self.url, let data = try? JSONEncoder().encode(self) else { return }
        try? data.write(to: url, options: [.atomic, .completeFileProtectionUntilFirstUserAuthentication])
    }

    static func reset() {
        if let url { try? FileManager.default.removeItem(at: url) }
    }
}

// MARK: - HTTP client

enum SyncError: LocalizedError {
    case notConfigured, unauthorized, wrongPassphrase, noPassphrase, alreadyHasPassphrase, badAddress
    case server(Int, String)
    case network(String)

    var errorDescription: String? {
        switch self {
        case .notConfigured: "Sync isn't set up."
        case .unauthorized: "The server rejected the token. Copy it again from: docker compose logs hush"
        case .wrongPassphrase: "That passphrase doesn't match the one this server was set up with."
        case .noPassphrase: "This server has no sync passphrase yet."
        case .alreadyHasPassphrase: "This server already has a sync passphrase. Choose \"Join\" and enter it."
        case .badAddress: "That doesn't look like a server address."
        case .server(let code, let msg): "Server error \(code): \(msg)"
        case .network(let msg): msg
        }
    }
}

struct SyncClient {
    struct Health: Decodable { var ok: Bool; var version: String; var `protocol`: Int? }
    struct Vault: Codable { var initialized: Bool; var salt: String?; var iterations: Int?; var check: String? }
    struct Stats: Decodable { var records: Int; var deleted: Int; var head: UInt64; var blobs: Int; var blobBytes: Int64; var version: String }
    struct Record: Codable { var id: String; var seq: UInt64; var deleted: Bool; var data: String? }
    struct PushRecord: Encodable { var id: String; var base: UInt64; var force: Bool; var deleted: Bool; var data: String? }
    struct PushResult: Decodable { var id: String; var ok: Bool?; var seq: UInt64?; var current: Record?; var error: String? }
    struct PushResponse: Decodable { var results: [PushResult]; var head: UInt64 }
    struct PullResponse: Decodable { var records: [Record]; var seq: UInt64; var head: UInt64; var more: Bool }

    let base: URL
    let token: String

    private static let session: URLSession = {
        let c = URLSessionConfiguration.ephemeral
        c.timeoutIntervalForRequest = 30
        c.timeoutIntervalForResource = 600
        c.waitsForConnectivity = false
        c.httpCookieStorage = nil
        c.urlCache = nil
        return URLSession(configuration: c)
    }()

    private func send(_ method: String, _ path: String, query: [URLQueryItem] = [], body: Data? = nil,
                      contentType: String = "application/json", auth: Bool = true) async throws -> Data {
        var comps = URLComponents(url: base.appending(path: path), resolvingAgainstBaseURL: false)
        if !query.isEmpty { comps?.queryItems = query }
        guard let url = comps?.url else { throw SyncError.badAddress }
        var req = URLRequest(url: url)
        req.httpMethod = method
        if auth { req.setValue("Bearer \(token)", forHTTPHeaderField: "Authorization") }
        if let body { req.httpBody = body; req.setValue(contentType, forHTTPHeaderField: "Content-Type") }
        let (data, resp): (Data, URLResponse)
        do {
            (data, resp) = try await Self.session.data(for: req)
        } catch let e as URLError {
            switch e.code {
            case .notConnectedToInternet, .networkConnectionLost: throw SyncError.network("No connection to your server. Is Tailscale on?")
            case .cannotFindHost, .dnsLookupFailed: throw SyncError.network("Can't find \(base.host() ?? "the server"). Check the address and that Tailscale is connected.")
            case .cannotConnectToHost, .timedOut: throw SyncError.network("Your server isn't answering. Is it running? (docker compose ps)")
            case .secureConnectionFailed, .serverCertificateUntrusted, .serverCertificateHasBadDate:
                throw SyncError.network("Secure connection failed. Turn on HTTPS Certificates in Tailscale, or use http:// on your home network.")
            case .appTransportSecurityRequiresSecureConnection:
                throw SyncError.network("Use https:// for this address (plain http only works for home-network and Tailscale IPs).")
            default: throw SyncError.network(e.localizedDescription)
            }
        }
        let code = (resp as? HTTPURLResponse)?.statusCode ?? 0
        if code == 401 { throw SyncError.unauthorized }
        guard (200..<300).contains(code) else {
            let msg = (try? JSONSerialization.jsonObject(with: data) as? [String: Any])?["error"] as? String
            if code == 409 { throw SyncError.alreadyHasPassphrase }
            throw SyncError.server(code, msg ?? HTTPURLResponse.localizedString(forStatusCode: code))
        }
        return data
    }

    private func json<T: Decodable>(_ t: T.Type, _ data: Data) throws -> T {
        do { return try JSONDecoder().decode(T.self, from: data) } catch { throw SyncError.network("This doesn't look like a Hush server.") }
    }

    func health() async throws -> Health { try json(Health.self, try await send("GET", "v1/health", auth: false)) }
    func vault() async throws -> Vault { try json(Vault.self, try await send("GET", "v1/vault")) }
    func stats() async throws -> Stats { try json(Stats.self, try await send("GET", "v1/stats")) }
    func putVault(_ v: Vault) async throws { _ = try await send("PUT", "v1/vault", body: try JSONEncoder().encode(v)) }
    func erase() async throws { _ = try await send("DELETE", "v1/vault", query: [URLQueryItem(name: "confirm", value: "erase")]) }

    func push(_ records: [PushRecord]) async throws -> PushResponse {
        let body = try JSONEncoder().encode(["records": records])
        return try json(PushResponse.self, try await send("POST", "v1/push", body: body))
    }

    func pull(since: UInt64) async throws -> PullResponse {
        try json(PullResponse.self, try await send("GET", "v1/pull", query: [URLQueryItem(name: "since", value: String(since)), URLQueryItem(name: "limit", value: "300")]))
    }

    func putBlob(_ id: String, _ data: Data) async throws {
        _ = try await send("PUT", "v1/blobs/\(id)", body: data, contentType: "application/octet-stream")
    }
    func getBlob(_ id: String) async throws -> Data { try await send("GET", "v1/blobs/\(id)") }
    func deleteBlob(_ id: String) async throws { _ = try await send("DELETE", "v1/blobs/\(id)") }
}
